16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be E.164: '+' followed by 8 to 15 digits")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "postcode")
55	    private String postcode;
56	
57	    @Column(name = "registration_date")
58	    private LocalDate registrationDate;
59	
60	    @Transient
61	    private String customerCode;
62	
63	    @Transient
64	    private Integer namesakeCount;
65	
66	    @Transient
67	    private Boolean bulkSignupWarning;
68	
69	    @Transient
70	    private Integer householdSize;
71	
72	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
73	    private Set<Pet> pets;
74	
75	    public String getAddress() {
76	        return this.address;
77	    }
78	
79	    public void setAddress(String address) {
80	        this.address = address;
81	    }
82	
83	    public String getCity() {
84	        return this.city;
85	    }
86	
87	    public void setCity(String city) {
88	        this.city = city;
89	    }
90	
91	    public String getTelephone() {
92	        return this.telephone;
93	    }
94	
95	    public void setTelephone(String telephone) {
96	        this.telephone = telephone;
97	    }
98	
99	    public String getEmail() {
100	        return this.email;
101	    }
102	
103	    /** Store the email lower-cased so it is persisted and returned in canonical form. */
104	    public void setEmail(String email) {
105	        this.email = (email == null) ? null : email.toLowerCase(Locale.ROOT);
106	    }
107	
108	    public String getPostcode() {
109	        return this.postcode;
110	    }
111	
112	    public void setPostcode(String postcode) {
113	        this.postcode = postcode;
114	    }
115	
116	    public LocalDate getRegistrationDate() {
117	        return this.registrationDate;
118	    }
119	
120	    /** Default a missing registration date to the server's current date. */
121	    public void setRegistrationDate(LocalDate registrationDate) {
122	        this.registrationDate = BusinessDay.adjust((registrationDate == null) ? LocalDate.now() : registrationDate);
123	    }
124	
125	    public String getCustomerCode() {
126	        return this.customerCode;
127	    }
128	
129	    public void setCustomerCode(String customerCode) {
130	        this.customerCode = customerCode;
131	    }
132	
133	    public Integer getNamesakeCount() {
134	        return this.namesakeCount;
135	    }
136	
137	    public void setNamesakeCount(Integer namesakeCount) {
138	        this.namesakeCount = namesakeCount;
139	    }
140	
141	    public Boolean getBulkSignupWarning() {
142	        return this.bulkSignupWarning;
143	    }
144	
145	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
146	        this.bulkSignupWarning = bulkSignupWarning;
147	    }
148	
149	    public Integer getHouseholdSize() {
150	        return this.householdSize;
151	    }
152	
153	    public void setHouseholdSize(Integer householdSize) {
154	        this.householdSize = householdSize;
155	    }
156	
157	    protected Set<Pet> getPetsInternal() {
158	        if (this.pets == null) {
159	            this.pets = new HashSet<>();
160	        }
161	        return this.pets;
162	    }
163	
164	    protected void setPetsInternal(Set<Pet> pets) {
165	        this.pets = pets;
166	    }
167	
168	    public List<Pet> getPets() {
169	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
170	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
171	        return Collections.unmodifiableList(sortedPets);
172	    }
173	
174	    public void setPets(List<Pet> pets) {
175	        this.pets = new HashSet<>(pets);
176	    }
177	
178	    public void addPet(Pet pet) {
179	        getPetsInternal().add(pet);
180	        pet.setOwner(this);
181	    }
182	
183	    /**
184	     * Return the Pet with the given name, or null if none found for this Owner.
185	     *
186	     * @param name to test
187	     * @return true if pet name is already in use
188	     */
189	    public Pet getPet(String name) {
190	        return getPet(name, false);
191	    }
192	
193	    /**
194	     * Return the Pet with the given name, or null if none found for this Owner.
195	     *
196	     * @param name to test
197	     * @return true if pet name is already in use
198	     */
199	    public Pet getPet(String name, boolean ignoreNew) {
200	        name = name.toLowerCase();
201	        for (Pet pet : getPetsInternal()) {
202	            if (!ignoreNew || !pet.isNew()) {
203	                String compName = pet.getName();
204	                compName = compName.toLowerCase();
205	                if (compName.equals(name)) {
206	                    return pet;
207	                }
208	            }
209	        }
210	        return null;
211	    }
212	
213	    public Pet getPet(Integer petId) {
214	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
215	    }
216	
217	    @Override
218	    public String toString() {
219	        return new ToStringCreator(this)
220	
221	            .append("id", this.getId())
222	            .append("new", this.isNew())
223	            .append("lastName", this.getLastName())
224	            .append("firstName", this.getFirstName())
225	            .append("address", this.address)
226	            .append("city", this.city)
227	            .append("telephone", this.telephone)
228	            .toString();
229	    }
230	}
