152	    @Override
153	    @Transactional(readOnly = true)
154	    public Collection<PetType> findAllPetTypes() throws DataAccessException {
155	        return petTypeRepository.findAll();
156	    }
157	
158	    @Override
159	    @Transactional
160	    public void savePetType(PetType petType) throws DataAccessException {
161	        petTypeRepository.save(petType);
162	    }
163	
164	    @Override
165	    @Transactional
166	    public void deletePetType(PetType petType) throws DataAccessException {
167	        petTypeRepository.delete(petType);
168	    }
169	
170	    @Override
171	    @Transactional(readOnly = true)
172	    public Specialty findSpecialtyById(int specialtyId) {
173	        return findEntityById(() -> specialtyRepository.findById(specialtyId));
174	    }
175	
176	    @Override
177	    @Transactional(readOnly = true)
178	    public Collection<Specialty> findAllSpecialties() throws DataAccessException {
179	        return specialtyRepository.findAll();
180	    }
181	
182	    @Override
183	    @Transactional
184	    public void saveSpecialty(Specialty specialty) throws DataAccessException {
185	        specialtyRepository.save(specialty);
186	    }
187	
