41	    /**
42	     * Normalise a telephone to E.164 for storage: keep an explicit leading '+' and country
43	     * code when present, otherwise assume '+61' and drop a single leading national '0'.
44	     * Spaces, dashes and brackets are stripped; the result must have 8 to 15 digits after
45	     * the '+', else the number is rejected as invalid.
46	     */
47	    @Named("normalizeTelephone")
48	    default String normalizeTelephone(String telephone) {
49	        if (telephone == null) {
50	            return null;
51	        }
52	        boolean international = telephone.trim().startsWith("+");
53	        String digits = telephone.replaceAll("\\D", "");
54	        if (!international) {
55	            if (digits.startsWith("0")) {
56	                digits = digits.substring(1);
57	            }
58	            digits = "61" + digits;
59	        }
60	        if (digits.length() < 8 || digits.length() > 15) {
61	            throw new IllegalArgumentException("Telephone cannot form a valid E.164 number: " + telephone);
62	        }
63	        org.springframework.samples.petclinic.service.E164NationalLength.check(digits);
64	        return "+" + digits;
65	    }
