18	import java.time.DayOfWeek;
19	import java.time.LocalDate;
20	
21	/**
22	 * Rolls a date forward onto a business day: a Saturday or Sunday becomes the
23	 * following Monday, any weekday is returned unchanged.
24	 */
25	public final class BusinessDay {
26	
27	    private BusinessDay() {
28	    }
29	
30	    public static LocalDate adjust(LocalDate date) {
31	        DayOfWeek dow = date.getDayOfWeek();
32	        if (dow == DayOfWeek.SATURDAY || dow == DayOfWeek.SUNDAY) {
33	            return date.plusDays(8 - dow.getValue());
34	        }
35	        return date;
36	    }
37	}
