133	     */
134	    @ExceptionHandler(IllegalArgumentException.class)
135	    @ResponseBody
136	    public ResponseEntity<ProblemDetail> handleIllegalArgumentException(IllegalArgumentException e, HttpServletRequest request) {
137	        HttpStatus status = HttpStatus.BAD_REQUEST;
138	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
139	        return ResponseEntity.status(status).body(detail);
