19	import java.util.Locale;
20	
21	import org.springframework.samples.petclinic.model.Owner;
22	
23	/**
24	 * Builds an owner's customerCode as '<CITY3>-<LAST3>-<NNNN>': the upper-cased first three
25	 * letters of the city, the first three of the last name, and a per-city 4-digit sequence
26	 * that is one more than the owners already registered in that city.
27	 */
28	public final class CustomerCodeGenerator {
29	
30	    private CustomerCodeGenerator() {
31	    }
32	
33	    public static String generate(Collection<Owner> existing, Owner owner) {
34	        String city = owner.getCity();
35	        String city3 = prefix(city);
36	        String last3 = prefix(owner.getLastName());
37	        long inCity = existing.stream().filter(o -> city.equalsIgnoreCase(o.getCity())).count();
38	        return String.format("%s-%s-%04d", city3, last3, inCity + 1);
39	    }
40	
41	    private static String prefix(String value) {
42	        return value.substring(0, Math.min(3, value.length())).toUpperCase(Locale.ROOT);
43	    }
44	}
