18	import java.nio.charset.StandardCharsets;
19	import java.util.Locale;
20	import java.util.UUID;
21	
22	import org.springframework.samples.petclinic.model.Owner;
23	
24	/**
25	 * Detects owners that belong to the same household: identical last name and address
26	 * once case and surrounding/duplicate whitespace are normalised.
27	 */
28	public final class HouseholdMatcher {
29	
30	    private HouseholdMatcher() {
31	    }
32	
33	    public static boolean sameHousehold(Owner a, Owner b) {
34	        return normalize(a.getLastName()).equals(normalize(b.getLastName()))
35	            && normalize(a.getAddress()).equals(normalize(b.getAddress()));
36	    }
37	
38	    /**
39	     * A stable identifier shared by every owner in the same household. Derived purely from
40	     * the normalised last name and address, so any two same-household owners produce the
41	     * same value without coordination.
42	     */
43	    public static String householdId(Owner owner) {
44	        String key = normalize(owner.getLastName()) + "\n" + normalize(owner.getAddress());
45	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
46	    }
47	
48	    private static String normalize(String value) {
49	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
50	    }
51	}
