21	/**
22	 * Normalises a free-text street address into a canonical form: trimmed, internal
23	 * whitespace collapsed to single spaces, upper-cased, with common street-type
24	 * abbreviations expanded (ST-&gt;STREET, RD-&gt;ROAD, AVE-&gt;AVENUE). Rejects an
25	 * address that is blank once normalised, since address is a required field.
26	 */
27	public final class AddressNormalizer {
28	
29	    private static final Map<String, String> ABBREVIATIONS =
30	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
31	
32	    private AddressNormalizer() {
33	    }
34	
35	    public static String normalize(String address) {
36	        String cleaned = address == null ? "" : address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
37	        if (cleaned.isEmpty()) {
38	            throw new IllegalArgumentException("Address must not be blank after normalization");
39	        }
40	        String[] words = cleaned.split(" ");
41	        for (int i = 0; i < words.length; i++) {
42	            words[i] = ABBREVIATIONS.getOrDefault(words[i], words[i]);
43	        }
44	        return String.join(" ", words);
45	    }
46	}
