20	/**
21	 * Validates an owner's optional 4-digit postcode against the postcode range of its
22	 * city's region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known
23	 * region ("UNKNOWN") accepts any 4-digit postcode.
24	 */
25	public final class PostcodeValidator {
26	
27	    private static final Map<String, int[]> REGION_RANGE = Map.of(
28	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
29	
30	    private PostcodeValidator() {
31	    }
32	
33	    /**
34	     * Return the postcode unchanged when absent or valid for the city's region; throw
35	     * {@link IllegalArgumentException} when a supplied postcode is out of range.
36	     */
37	    public static String validate(String city, String postcode) {
38	        if (postcode == null) {
39	            return null;
40	        }
41	        int[] range = REGION_RANGE.get(LocalityResolver.locality(city));
42	        int value = Integer.parseInt(postcode);
43	        if (range != null && (value < range[0] || value > range[1])) {
44	            throw new IllegalArgumentException("Postcode " + postcode + " is not valid for city " + city);
45	        }
46	        return postcode;
47	    }
48	}
