5	/**
6	 * Validates an E.164 number's national-number length against its country code:
7	 * '+61' requires 9 national digits, '+1' requires 10. Country codes without a
8	 * known requirement are accepted unchanged.
9	 */
10	public final class E164NationalLength {
11	
12	    private E164NationalLength() {
13	    }
14	
15	    /** Country code (digits, no '+') -> required national-number digit count. */
16	    private static final Map<String, Integer> REQUIRED = Map.of("1", 10, "61", 9);
17	
18	    /**
19	     * @param digits the E.164 digits: country code followed by the national number, no '+'
20	     * @throws IllegalArgumentException if the national-number length is wrong for the country
21	     */
22	    public static void check(String digits) {
23	        for (Map.Entry<String, Integer> rule : REQUIRED.entrySet()) {
24	            String code = rule.getKey();
25	            if (digits.startsWith(code)) {
26	                if (digits.length() - code.length() != rule.getValue()) {
27	                    throw new IllegalArgumentException(
28	                        "National number for +" + code + " must be " + rule.getValue() + " digits: +" + digits);
29	                }
30	                return;
31	            }
32	        }
33	    }
34	}
